"""Export frozen contracts to shared/ (D31): JSON Schemas + TypeScript types
generated from the Python Pydantic models — one source, two artifacts, no drift.

Usage: uv run python scripts/export_contracts.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

SHARED = Path(__file__).resolve().parents[1] / "shared"

TS_HEADER = """\
// AUTO-GENERATED by scripts/export_contracts.py — do not edit by hand.
// Source of truth: sidecar pydantic models (docs/04 §6, D31).
"""


def to_ts_type(schema: dict, indent: str = "  ") -> list[str]:
    """Minimal, readable JSON-Schema -> TypeScript interface emitter for the
    flat shapes used by our contracts (object properties with primitive or
    optional primitive types)."""
    lines: list[str] = []
    required = set(schema.get("required", []))
    defs = schema.get("$defs") or schema.get("definitions") or {}

    def resolve(prop: dict) -> dict:
        ref = prop.get("$ref")
        if ref and ref.startswith("#/$defs/"):
            return defs[ref.removeprefix("#/$defs/")]
        return prop

    for name, raw_prop in schema.get("properties", {}).items():
        prop = resolve(raw_prop)
        ts_types: list[str] = []
        type_ref = prop.get("type")
        any_of = prop.get("anyOf")
        if isinstance(type_ref, list):  # e.g. ["string", "null"]
            type_ref = next((t for t in type_ref if t != "null"), None)
        if any_of:
            type_ref = next((t.get("type") for t in any_of if t.get("type") != "null"), None)
        ts_map = {"string": "string", "number": "number", "boolean": "boolean",
                  "integer": "number", "object": "Record<string, unknown>"}
        if type_ref == "array":
            raw_items = prop.get("items", {})
            ref_name = raw_items.get("$ref", "").split("/")[-1]
            items = resolve(raw_items)
            if items.get("properties") and ref_name:
                ts_types.append(f"{ref_name}[]")
            else:
                items_type = items.get("type")
                ts_types.append(f"{ts_map.get(items_type, 'unknown')}[]")
        elif type_ref:
            ts_types.append(ts_map.get(type_ref, "unknown"))
        enum = prop.get("enum") or next(
            (t.get("enum") for t in (any_of or []) if t.get("enum")), None
        )
        if enum:
            ts_types = [" | ".join(json.dumps(v) for v in enum)]
        optional = "" if name in required else "?"
        lines.append(f"{indent}{name}{optional}: {' | '.join(ts_types)};")
    return lines


def main() -> int:
    from sidecar.contracts import (
        CONTRACTS_VERSION,
        STAGES,
        TASK_STATUSES,
        Done,
        Progress,
        StageChanged,
        TaskError,
    )
    from sidecar.observations import perception_json_schema
    from sidecar.taxonomy import Taxonomy

    schemas_dir = SHARED / "schemas"
    schemas_dir.mkdir(parents=True, exist_ok=True)
    event_models = [StageChanged, Progress, TaskError, Done]

    # --- JSON Schemas ---------------------------------------------------
    events_schema = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "TaskEvents",
        "version": CONTRACTS_VERSION,
        "stages": list(STAGES),
        "task_statuses": list(TASK_STATUSES),
        "definitions": {},
    }
    for model in event_models:
        events_schema["definitions"][model.__name__] = model.model_json_schema()
    (schemas_dir / "task-events.schema.json").write_text(
        json.dumps(events_schema, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )

    taxonomy_schema = Taxonomy.model_json_schema()
    taxonomy_schema.update(
        {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Taxonomy"}
    )
    (schemas_dir / "taxonomy.schema.json").write_text(
        json.dumps(taxonomy_schema, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )

    obs = perception_json_schema()
    obs.update({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "Observations",
        "version": CONTRACTS_VERSION,
    })
    (schemas_dir / "observations.schema.json").write_text(
        json.dumps(obs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )

    # --- TypeScript ------------------------------------------------------
    ts_lines = [TS_HEADER]
    ts_lines.append(f"export const CONTRACTS_VERSION = {CONTRACTS_VERSION};\n")
    ts_lines.append(
        "export type TaskStage = " + " | ".join(json.dumps(s) for s in STAGES) + ";"
    )
    ts_lines.append(
        "export type TaskStatus = " + " | ".join(json.dumps(s) for s in TASK_STATUSES) + ";\n"
    )
    for model in event_models:
        schema = model.model_json_schema()
        ts_lines.append(f"export interface {model.__name__} {{")
        ts_lines.extend(to_ts_type(schema))
        ts_lines.append("}\n")
    ts_lines.append("export interface TaxonomyType {")
    taxonomy_schema = Taxonomy.model_json_schema()
    type_item = taxonomy_schema["$defs"]["TaxonomyType"]
    ts_lines.extend(to_ts_type(type_item))
    ts_lines.append("}")
    ts_lines.append("export interface Taxonomy {")
    ts_lines.extend(to_ts_type(taxonomy_schema))
    ts_lines.append("}\n")
    ts_lines.append("export interface Observation {")
    ts_lines.extend(to_ts_type(obs))
    ts_lines.append("}")
    ts_lines.append("export const OBSERVATION_TAGS: string[] = " +
                    json.dumps(obs["properties"]["tags"]["items"]["enum"]) + ";")
    (SHARED / "types.ts").write_text("\n".join(ts_lines) + "\n", encoding="utf-8")

    print(f"contracts exported to {SHARED} (version {CONTRACTS_VERSION})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
